/* Vastar port - Z80 CPU emulator
 *
 * Two implementations with the same interface and the same state:
 *   z80.c       portable C (PC, and the reference on the Amiga)
 *   z80_68k.s   68k assembler for the Amiga (generated by tools/gen_z80_68k.py);
 *               in that build the C version is called z80c_run()
 *
 * Memory model: every CPU sees a flat 64 KB array (`mem`, plus 4 guard bytes) that
 * is read directly. Writes go by 256 byte page through `wtype`:
 *   Z80_RAM     plain store
 *   Z80_ROM     ignored
 *   Z80_MIRROR  stored here and in wmirror[page] (RAM shared by two CPUs, mirrors)
 *   Z80_IO      the write handler
 * Whatever a CPU reads must be kept up to date in its array by the machine.
 *
 * All documented instructions plus the undocumented ones (IXH/IXL, SLL, DDCB
 * register copies, X/Y flags) are implemented. Cycle counts are per instruction.
 */
#ifndef Z80_H
#define Z80_H

#include <stdint.h>

typedef uint8_t (*z80_read_fn)(void *ctx, uint16_t addr);
typedef void (*z80_write_fn)(void *ctx, uint16_t addr, uint8_t value);

enum { Z80_RAM, Z80_ROM, Z80_MIRROR, Z80_IO };

/* The layout is fixed: z80_68k.s uses these offsets (checked in z80.c). */
typedef struct Z80 {
    uint8_t a, f, b, c, d, e, h, l;           /*  0: big endian pairs: BC at 2, DE at 4, HL at 6 */
    uint8_t a2, f2, b2, c2, d2, e2, h2, l2;   /*  8: shadow registers */
    uint16_t ix, iy, sp, pc, wz;              /* 16 */
    uint8_t i, r, r7, iff1, iff2, im;         /* 26: r counts freely, r7 = bit 7 set by LD R,A */
    uint8_t halted, after_ei, nmi_pending;    /* 32 */
    uint8_t irq_line;                         /* 35: level of the INT line */
    uint8_t irq_hold;                         /* 36: clear irq_line when the interrupt is taken */
    uint8_t irq_vector;                       /* 37: data bus in IM 0 / IM 2 (0xff = RST 38h) */
    uint8_t ei_window, pad0;                  /* 38: used by z80_68k.s */
    int32_t icount;                           /* 40: cycles left in the current z80_run() */
    int32_t ei_save;                          /* 44: used by z80_68k.s */
    int32_t start;                            /* 48: used by z80_68k.s */
    uint8_t *mem;                             /* 52 */
    z80_write_fn write;                       /* 56: Z80_IO pages */
    z80_read_fn in;                           /* 60 */
    z80_write_fn out;                         /* 64 */
    void *ctx;                                /* 68 */
    uint8_t wtype[256];                       /* 72 */
    uint8_t *wmirror[256];                    /* 328 */
} Z80;

/* mem: 64 KB + 4 bytes; all pages Z80_RAM, I/O reads 0xff and writes are ignored */
void z80_init(Z80 *z, uint8_t *mem);
void z80_reset(Z80 *z);

/* pages [start, end] (inclusive, 256 byte aligned) get a write type; for Z80_MIRROR,
   mirror is where `start` is mirrored to (the following pages follow it) */
void z80_set_wtype(Z80 *z, uint16_t start, uint16_t end, int type, uint8_t *mirror);

/* execute at least `cycles` cycles; returns the cycles actually used (overshoot is
   carried over to the next call) */
int z80_run(Z80 *z, int cycles);
int z80c_run(Z80 *z, int cycles);   /* the C core, in builds with the assembler core */

void z80_nmi(Z80 *z);
void z80_set_irq(Z80 *z, int level, int hold);

/* tables shared with z80_68k.s, filled by z80_init() */
extern uint8_t z80_tables[1056];
extern uint16_t z80_daa[0x1400];

#endif
